{"name": "create_employee_performance_analysis_table", "query": "
-- ============================================================
--  TABLE 1: employee_performance_analysis
--  Scope: active employees (salary.to_date = '9999-01-01')
-- ============================================================
CREATE TABLE IF NOT EXISTS employees.employee_performance_analysis (
  employee_id          bigint       NOT NULL,
  performance_category varchar(20)  NOT NULL,
  salary_growth_rate   decimal(8,2) NOT NULL,
  days_of_service      integer      NOT NULL,
  promotion_count      integer      NOT NULL,

  CONSTRAINT pk_employee_performance_analysis PRIMARY KEY (employee_id),

  CONSTRAINT chk_performance_category
    CHECK (performance_category IN ('high_achiever', 'steady_performer', 'needs_attention')),

  CONSTRAINT chk_days_of_service   CHECK (days_of_service   >= 0),
  CONSTRAINT chk_promotion_count   CHECK (promotion_count   >= 0)
);

COMMENT ON TABLE  employees.employee_performance_analysis                        IS 'Career progression & performance classification for all currently active employees.';
COMMENT ON COLUMN employees.employee_performance_analysis.employee_id            IS 'References employees.employee.id — the subject employee.';
COMMENT ON COLUMN employees.employee_performance_analysis.performance_category   IS 'high_achiever | steady_performer | needs_attention — derived from salary growth and tenure.';
COMMENT ON COLUMN employees.employee_performance_analysis.salary_growth_rate     IS 'Percentage change from first ever salary to current active salary.';
COMMENT ON COLUMN employees.employee_performance_analysis.days_of_service        IS 'Calendar days between hire_date and today.';
COMMENT ON COLUMN employees.employee_performance_analysis.promotion_count        IS 'Number of distinct job titles held across career.';
"}

{"name": "create_department_salary_analysis_table", "query": "
-- ============================================================
--  TABLE 2: department_salary_analysis
--  Scope: current salary stats across active employees only
-- ============================================================
CREATE TABLE IF NOT EXISTS employees.department_salary_analysis (
  department_name     varchar(40)    NOT NULL,
  avg_current_salary  decimal(10,2)  NOT NULL,
  employee_count      integer        NOT NULL,
  salary_range_spread integer        NOT NULL,

  CONSTRAINT pk_department_salary_analysis PRIMARY KEY (department_name),

  CONSTRAINT chk_employee_count      CHECK (employee_count      >= 0),
  CONSTRAINT chk_salary_range_spread CHECK (salary_range_spread >= 0)
);

COMMENT ON TABLE  employees.department_salary_analysis                          IS 'Salary equity metrics aggregated per department for active employees — used for pay-equity analysis.';
COMMENT ON COLUMN employees.department_salary_analysis.department_name          IS 'Human-readable department name from employees.department.';
COMMENT ON COLUMN employees.department_salary_analysis.avg_current_salary       IS 'Mean active salary across all current employees in the department.';
COMMENT ON COLUMN employees.department_salary_analysis.employee_count           IS 'Count of current employees (active salary record) in the department.';
COMMENT ON COLUMN employees.department_salary_analysis.salary_range_spread      IS 'MAX(salary) – MIN(salary) for current employees — proxy for within-department pay disparity.';
"}
